        # + 1 MiB for the multipart envelope
        if declared.isdigit() and int(declared) > MAX_UPLOAD_BYTES + 1024 * 1024:
            return JSONResponse(
                {"detail": f"File too large (limit {MAX_UPLOAD_BYTES // (1024 * 1024)} MB)."},
                status_code=413,
            )
    return await call_next(request)

def remove_file_from_user(self, user_id: str, file_id: str) -> bool:
    try:
        with self._connection() as con:
            cur = con.execute(
                "DELETE FROM user_files WHERE user_id = ? AND file_id = ?",
                (user_id, file_id),
            )
        removed = cur.rowcount > 0
        if removed:
            self.logger.info(f"Removed file {file_id[:8]} from user {user_id[:8]}")
        return removed
    except Exception as e:
        self.logger.error(f"remove_file_from_user failed: {e}")
        return False

def _delete_file_everywhere(file_id: str, indexer=None) -> Optional[str]:
    """
    Remove a file's embeddings, then its SQLite rows. Chroma goes first so a failure leaves the
    DB rows in place (and the file recorded in `pending_deletions`) instead of orphan embeddings
    that still hold the user's text. Returns None on success, else the error text.
    """
    try:
        (indexer or VectorIndexer()).delete_embeddings_for_file(file_id)
    except Exception as e:
        attempts = db.record_pending_deletion(file_id, str(e))
        logger.warning(
            f"Chroma cleanup failed for {file_id[:8]} (attempt {attempts}); "
            f"keeping DB rows for a retry: {e}"
        )
        return str(e)
    if not db.delete_file(file_id) and db.get_file_name(file_id) is not None:
        db.record_pending_deletion(file_id, "database delete failed")
        return "database delete failed"
    return None  # delete_file also cleared any pending_deletions row

def _process_chunk(self, chunk: Dict, context_str: str) -> Tuple[bool, str]:
    """
    Enrich one chunk. Raises LLMUnavailable if the server fails; in that case nothing is
    left behind for the chunk (no rejection rows, no enrichment row), so it stays pending.
    """
    self.llm.reset_stats()
    try:
        return self._process_chunk_impl(chunk, context_str)
    except LLMUnavailable:
        # get_pending_files() treats an enrichment row as "attempted"; drop it.
        self.db.delete_enrichment(chunk["chunk_id"])
        raise
    finally:
        st = self.llm.stats
        if st["calls"]:
            logger.info(
                f"Chunk {chunk['chunk_id'][:8]}: {st['calls']} LLM call(s), "
                f"{st['seconds']:.1f}s, tokens in/out "
                f"{st['prompt_tokens']}/{st['completion_tokens']}"
            )

