@classmethod
def _get_ce_model(cls) -> Optional[CrossEncoder]:
    """
    Shared NLI cross-encoder. It is optional: if loading fails or is interrupted we degrade
    to bi-encoder-only scoring and stop retrying (`_ce_skipped`), so the session can report
    "bi-encoder only" instead of silently showing no NLI data.
    """
    if cls._ce_skipped or not BGE_AVAILABLE:
        return None
    try:
        return models.get_cross_encoder(CE_NLI_MODEL)
    except KeyboardInterrupt:
        cls._ce_skipped = True
        logger.warning(
            "Cross-encoder download interrupted. Continuing with bi-encoder scoring only."
        )
    except Exception as e:
        cls._ce_skipped = True
        logger.error(
            f"Cross-encoder failed to load: {e}  Continuing with bi-encoder scoring only."
        )
    return None

