class ChromaVerifier:
    COLLECTION = "qa_pairs"

    def __init__(self, persist_directory: str = str(CHROMA_DIR)):
        self._collection = None
        self._model: Optional[SentenceTransformer] = None
        self._ready = False
        if not CHROMA_AVAILABLE or not Path(persist_directory).exists():
            return
        try:
            client = chromadb.PersistentClient(path=persist_directory)
            self._collection = client.get_collection(self.COLLECTION)
            self._ready = self._collection.count() > 0
        except Exception as e:
            logger.debug(f"Chroma collection unavailable: {e}")

    @property
    def ready(self) -> bool:
        return self._ready

    def count(self) -> int:
        if not self._ready:
            return 0
        try:
            return self._collection.count()
        except Exception:
            return 0

    def _get_model(self) -> Optional[SentenceTransformer]:
        if not BGE_AVAILABLE:
            return None
        if self._model is None:
            self._model = models.get_bi_encoder(BGE_MODEL)
        return self._model

    def query(self, text: str, n: int = 3) -> List[Dict]:
        if not self._ready:
            return []
        model = self._get_model()
        if not model:
            return []
        try:
            embedding = model.encode(text, normalize_embeddings=True).tolist()
            results = self._collection.query(
                query_embeddings=[embedding],
                n_results=min(n, self._collection.count()),
                include=["documents", "metadatas", "distances"],
            )
            hits = []
            for qid, doc, meta, dist in zip(
                results.get("ids", [[]])[0],
                results.get("documents", [[]])[0],
                results.get("metadatas", [[]])[0],
                results.get("distances", [[]])[0],
            ):
                hits.append(
                    {
                        "question_id": qid,
                        "document": doc,
                        "score": round(1.0 - dist, 4),
                        "metadata": meta,
                    }
                )
            return hits
        except Exception as e:
            logger.warning(f"ChromaVerifier.query failed: {e}")
            return []

class QAVectorStore:
    """Thin wrapper around a ChromaDB collection for Q&A pairs."""

    COLLECTION_NAME = "qa_pairs"

    def __init__(self, persist_directory: str = CHROMA_DIR):
        if not CHROMA_AVAILABLE:
            raise ImportError("chromadb is not installed")
        self._client = chromadb.PersistentClient(path=persist_directory)
        self._collection = self._client.get_or_create_collection(
            self.COLLECTION_NAME,
            metadata={"hnsw:space": "cosine"},
        )
        logger.info(
            f"QAVectorStore ready — {self._collection.count()} document(s) in collection"
        )

    def add_qa_pair(
        self,
        question_id: str,
        question_text: str,
        answer_text: str,
        embedding: List[float],
        metadata: Optional[Dict[str, Any]] = None,
    ) -> None:
        combined = f"Question: {question_text}\nAnswer: {answer_text}"
        self._collection.upsert(
            ids=[question_id],
            documents=[combined],
            embeddings=[embedding],
            metadatas=[metadata or {}],
        )

    def query(
        self,
        query_embedding: List[float],
        n_results: int = 5,
        where: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        kwargs: Dict[str, Any] = {
            "query_embeddings": [query_embedding],
            "n_results": n_results,
            "include": ["documents", "metadatas", "distances"],
        }
        if where:
            kwargs["where"] = where
        return self._collection.query(**kwargs)

    def delete_by_ids(self, ids: List[str]) -> None:
        """Remove specific document IDs from the collection."""
        if ids:
            self._collection.delete(ids=ids)
            logger.info(f"Deleted {len(ids)} embedding(s) from Chroma")

    def count(self) -> int:
        return self._collection.count()

def chroma_file_ids(collection) -> Dict[str, str]:
    """{chroma id: file_id ('' when the metadata has none)} for every document."""
    out: Dict[str, str] = {}
    offset = 0
    while True:
        page = collection.get(include=["metadatas"], limit=_PAGE, offset=offset)
        ids = page.get("ids") or []
        if not ids:
            return out
        for cid, meta in zip(ids, page.get("metadatas") or [{}] * len(ids)):
            out[cid] = str((meta or {}).get("file_id") or "")
        offset += len(ids)

def find_similar_questions(
    self,
    question_text: str,
    top_k: int = 5,
    min_similarity: float = 0.80,
) -> List[Dict[str, Any]]:
    query_vec = self._embed(question_text)

    results = self.collection.query(
        query_embeddings=[query_vec],
        n_results=top_k,
        # Filter to only match against questions, not answers
        where={"type": "question"},
    )

    filtered = []
    if results["ids"]:
        for i in range(len(results["ids"][0])):
            dist = results["distances"][0][i]
            # If using cosine distance: Similarity = 1 - Distance
            similarity = 1.0 - dist

            if similarity >= min_similarity:
                filtered.append(
                    {
                        "id": results["ids"][0][i],
                        "question": results["documents"][0][i],
                        "metadata": results["metadatas"][0][i],
                        "similarity": round(similarity, 3),
                    }
                )

    return filtered

def persist(self):
    # In modern Chroma (PersistentClient), data is auto-persisted.
    # This method is kept for API compatibility but does nothing.
    pass

