def _tokens(text: str) -> Set[str]:
    """Every token that could be new information: words (also 3-letter ones such as "two"),
    numbers and single-letter symbols."""
    return {
        _stem(w)
        for w in re.findall(r"[a-z0-9]+", text.lower())
