def generate_question_candidates(self, chunk: Dict, context_str: str) -> List[Dict]:
    estimated_tokens = chunk.get("estimated_tokens", 150)
    per_diff = get_questions_per_difficulty(estimated_tokens)
    content_type = chunk.get("content_type", "prose")

    if self.prompts.combined:
        return self._generate_combined(chunk, context_str, per_diff, content_type)

    difficulty_instructions = self.prompts.difficulty_instructions(content_type)
    all_candidates: List[Dict] = []

    for difficulty, instruction in difficulty_instructions.items():
        prompt = self.prompts.questions(
            chunk["content"], context_str, difficulty, instruction, per_diff
        )
        sys_prompt, user_prompt = prompt.system, prompt.user
        result = self._call_model(sys_prompt, user_prompt, QUESTIONS_ANSWER_TOKENS)
        raw = result.get("qa_pairs", [])

        if not raw and result:
            from collections import defaultdict

            groups: dict = defaultdict(dict)
            for k, v in result.items():
                m = re.match(r"^(question|source_quote)(\d*)$", k)
                if m:
                    groups[m.group(2)][m.group(1)] = v
            flat_items = [g for g in groups.values() if "question" in g]
            if flat_items:
                raw = flat_items

        count = 0
        for item in raw:
            if count >= per_diff:
                break
            if not isinstance(item, dict):
                continue
            item["difficulty"] = difficulty
            all_candidates.append(item)
            count += 1

    return self._deduplicate_candidates(all_candidates)

    def combined_qa(self, chunk_content: str, context: str, per_diff: int, content_type: str) -> Prompt:
        levels = self.difficulty_instructions(content_type)
        level_lines = "\n".join(f"- {name}: {text}" for name, text in levels.items())
        system = (
            "You are an expert interviewer who writes precise questions and short, faithful model "
            "answers from a source text. Output ONLY valid JSON."
        )
        user = f"""\
### BACKGROUND CONTEXT (orientation only, never a source):
{context}

### TARGET TEXT CHUNK (the only source):
{chunk_content}

### TASK
Write up to {per_diff} question(s) for EACH level, each with a model answer:
{level_lines}

### QUESTION RULES
{self.question_rules}

### ANSWER RULES (the answer must be supported by that question's source_quote)
{self.answer_rules}
{self._examples()}
### OUTPUT (JSON only)
{{"qa_pairs": [ {{"question": "...", "source_quote": "...", "answer": "...", "difficulty": "Easy|Medium|Hard"}} ]}}
"""
        return Prompt(system, user)

def _generate_combined(
    self, chunk: Dict, context_str: str, per_diff: int, content_type: str
) -> List[Dict]:
    """One call returns questions AND answers (prompt sets with combined=True)."""
    prompt = self.prompts.combined_qa(chunk["content"], context_str, per_diff, content_type)
    result = self._call_model(prompt.system, prompt.user, 600 + 350 * per_diff * 3)
    raw = result.get("qa_pairs", [])
    levels = list(self.prompts.difficulty_instructions(content_type))
    candidates: List[Dict] = []
    counts: Dict[str, int] = {}
    for item in raw if isinstance(raw, list) else []:
        if not isinstance(item, dict):
            continue
        level = str(item.get("difficulty", "")).strip().capitalize()
        if level not in levels:
            continue
        if counts.get(level, 0) >= per_diff:
            continue
        counts[level] = counts.get(level, 0) + 1
        item["difficulty"] = level
        candidates.append(item)
    return self._deduplicate_candidates(candidates)

def check_health(self) -> None:
    """Raise LLMUnavailable unless the server answers /v1/models right now."""
    try:
        self.client.with_options(timeout=LLM_HEALTH_TIMEOUT_S, max_retries=0).models.list()
    except openai.APIError as e:
        raise LLMUnavailable(f"LLM server is not responding: {e}") from e

def _strip_thinking(content: str) -> str:
    """Drop inline <think> blocks (servers started with --reasoning-format none leave them in
    `content`; an unterminated block means the budget ran out mid-thought)."""
    return _THINK_BLOCK.sub("", content).strip()

def _load_model(self, model_name: str, label: str):
    """
    Context manager that shows the right UI for model loading:

    • Already cached → transient Rich spinner (loads in ~1-3s, no output needed)
    • Not cached     → step out of Rich entirely so HuggingFace's own tqdm
                       download bars can render cleanly to stderr, then print
                       a completion message when done

    The 'with' block should call the actual model constructor.
    """
    cached = self._is_cached(model_name)

    if cached:
        # Fast path — weights already on disk, just mmap them
        return self._spinner(f"{label} (loading from cache)…")

    # Slow path — first download. Rich would swallow tqdm, so don't use it.
    class _DownloadCtx:
        def __enter__(self_):
            if RICH_AVAILABLE:
                # Temporarily pause Rich's live display so tqdm can write freely
                console.print(
                    f"[yellow]▶ Downloading[/] [bold]{model_name}[/] "
                    f"[dim](first run — this may take a minute)[/]"
                )
            else:
                print(f"  Downloading {model_name} (first run)…")
            return self_

        def __exit__(self_, *_):
            if RICH_AVAILABLE:
                console.print(
                    f"[green]✓ Downloaded[/] [bold]{model_name}[/]  "
                    f"[dim]Cached for future runs.[/]"
                )
            else:
                print(f"  ✓ {model_name} downloaded and cached.")

    return _DownloadCtx()

