    COLLECTION = "qa_pairs"

    def __init__(self, persist_directory: str = str(CHROMA_DIR)):
        self._collection = None
        self._model: Optional[SentenceTransformer] = None
        self._ready = False
        if not CHROMA_AVAILABLE or not Path(persist_directory).exists():
            return
        try:
            client = chromadb.PersistentClient(path=persist_directory)
            self._collection = client.get_collection(self.COLLECTION)
            self._ready = self._collection.count() > 0
        except Exception as e:
            logger.debug(f"Chroma collection unavailable: {e}")

    @property
    def ready(self) -> bool:
        return self._ready

    def count(self) -> int:
        if not self._ready:
            return 0
        try:
            return self._collection.count()
        except Exception:
            return 0

    def _get_model(self) -> Optional[SentenceTransformer]:
        if not BGE_AVAILABLE:
            return None
        if self._model is None:
            self._model = models.get_bi_encoder(BGE_MODEL)
        return self._model

    def query(self, text: str, n: int = 3) -> List[Dict]:
        if not self._ready:
            return []
        model = self._get_model()
        if not model:
            return []
        try:
            embedding = model.encode(text, normalize_embeddings=True).tolist()
            results = self._collection.query(
                query_embeddings=[embedding],
                n_results=min(n, self._collection.count()),
                include=["documents", "metadatas", "distances"],
            )
            hits = []
            for qid, doc, meta, dist in zip(
                results.get("ids", [[]])[0],
                results.get("documents", [[]])[0],
                results.get("metadatas", [[]])[0],
                results.get("distances", [[]])[0],
            ):
                hits.append(
                    {
                        "question_id": qid,
                        "document": doc,
                        "score": round(1.0 - dist, 4),
                        "metadata": meta,
                    }
                )
            return hits
        except Exception as e:
            logger.warning(f"ChromaVerifier.query failed: {e}")
            return []

def _canon(text: str) -> Tuple[str, List[int]]:
    """Lower-case alphanumerics only, with the index of each kept character in `text`."""
    chars, index = [], []
    for i, ch in enumerate(text):
        if ch.isalnum():
            chars.append(ch.lower())
            index.append(i)
    return "".join(chars), index

