        if tokens < MIN_TOKENS_FOR_METADATA:
            self.db.save_rejections(
                chunk_id, [{"reason": "Too short for metadata"}]
            )
            return True, ""
        self.db.save_rejections(
            chunk_id, [{"reason": "Metadata generation failed"}]
        )
        return False, ""

    meta["tags"] = self.llm._normalize_tags(meta.get("tags", []))
    meta["tags"] = self.llm._verify_tags_grounded(meta["tags"], content)
    meta["triplets"] = self.llm._verify_triplets_grounded(
        meta.get("triplets", []), content
    )
    self.db.save_enrichment(chunk_id, meta)

    if tokens < MIN_TOKENS_FOR_QA:
        return True, meta.get("summary", "")

    candidates = self.llm.generate_question_candidates(chunk, context_str)
    all_valid_qa: List[Dict] = []
    rejected_qa: List[Dict] = []

@staticmethod
def _verify_tags_grounded(tags: List[str], text: str) -> List[str]:
    text_lower = text.lower()
    grounded = []
    for tag in tags:
        surface = tag.replace("_", " ")
        if surface in text_lower or tag in text_lower:
            grounded.append(tag)
    return grounded

def _call_model(
    self, sys_prompt: str, user_prompt: str, answer_tokens: int = METADATA_ANSWER_TOKENS
) -> Dict[str, Any]:
    return self._extract_json(self._chat(sys_prompt, user_prompt, answer_tokens))

def judge_from_env(env: Optional[Mapping[str, str]] = None) -> Optional[D1Judge]:
    """The optional judge chosen by QP_VERIFY_JUDGE (unset, "off" or "none": no judge). Only "d1" exists; it needs
    LIQUID_API_KEY and reads QP_D1_THRESHOLD (default D1_DEFAULT_THRESHOLD). Raises ValueError for a bad setting."""
    env = os.environ if env is None else env
    name = env.get("QP_VERIFY_JUDGE", "").strip().lower()
    if name in ("", "off", "none", "0", "false"):
        return None
    if name != "d1":
        raise ValueError(f"unknown QP_VERIFY_JUDGE '{name}'; the only judge is 'd1'")
    key = env.get("LIQUID_API_KEY", "").strip()
    if not key:
        raise ValueError("QP_VERIFY_JUDGE=d1 needs LIQUID_API_KEY in the environment")
    return D1Judge(key, threshold=float(env.get("QP_D1_THRESHOLD", D1_DEFAULT_THRESHOLD)))

def _looks_cut_off(text: str, reference: str = "") -> bool:
    """True when the answer stops mid-sentence: no closing punctuation and it ends on a function word
    ("... sends an"), on a pronoun after a subordinator ("... before it"), or on a truncated word that starts a
    longer word of the reference ("... passed through a soft"). Short but complete answers are not cut off."""
    t = text.strip()
    if not t or t[-1] in _TERMINAL:
        return False
    words = re.findall(r"[A-Za-z']+", t.lower())
    if not words:
        return False
    last = words[-1]
    if last in _DANGLING:
        return True
    if len(words) >= 2 and last in _PRONOUNS and words[-2] in _SUBORDINATORS:
        return True
    ref_words = set(re.findall(r"[A-Za-z']+", reference.lower()))
    return len(last) >= 3 and last not in ref_words and any(w.startswith(last) and len(w) > len(last) for w in ref_words)

def get_prompt_set(name: str = "") -> PromptSet:
    """Resolve a prompt set by name, defaulting to QP_PROMPT_SET, then DEFAULT_PROMPT_SET."""
    name = (name or os.environ.get("QP_PROMPT_SET", "") or DEFAULT_PROMPT_SET).strip().lower()
    try:
        return PROMPT_SETS[name]
    except KeyError:
        raise ValueError(f"unknown prompt set '{name}'; choose from {sorted(PROMPT_SETS)}") from None

class SharedModel:
    """Wraps a sentence-transformers model so concurrent callers (an enrichment run and interview
    scoring, say) take turns in encode()/predict(). Hugging Face fast tokenizers can raise
    "Already borrowed" when used from several threads at once, and on one GPU the calls would
    queue anyway. Everything else is delegated untouched."""

    def __init__(self, model: Any):
        self._model = model
        self._lock = threading.RLock()

    def encode(self, *args, **kwargs):
        with self._lock:
            return self._model.encode(*args, **kwargs)

    def predict(self, *args, **kwargs):
        with self._lock:
            return self._model.predict(*args, **kwargs)

    def __getattr__(self, name):  # only reached for attributes not defined above
        return getattr(self._model, name)

