class JudgeUnavailable(RuntimeError):
    """The judge cannot give a verdict right now (bad key, network failure, repeated rate limiting). Says nothing
    about the pair, so callers must not record a rejection for it; Enricher turns it into LLMUnavailable."""

class SpeechToText:
    def __init__(self):
        model_id, tried = resolve_asr_model()  # QP_ASR_MODEL, a local folder, or the Hugging Face id
        try:
            self.model = Qwen3ASRModel.from_pretrained(
                model_id, dtype=torch.float32, device_map="cpu"
            )
        except OSError as e:
            raise RuntimeError(load_error_message(model_id, tried, e)) from e
        self.audio_buffer = []

    def _transcribe_array(self, audio_np: np.ndarray, sample_rate: int = 16000) -> str:
        # FIX1: soundfile is now imported at module level, not here.
        with tempfile.NamedTemporaryFile(suffix=".wav", delete=False) as tmp:
            tmp_path = tmp.name
        try:
            sf.write(tmp_path, audio_np, sample_rate, subtype="PCM_16")
            result = self.model.transcribe(audio=tmp_path, language="English")
            return result[0].text if result else ""
        finally:
            Path(tmp_path).unlink(missing_ok=True)

    def transcribe_chunk(self, byte_chunk: bytes) -> str:
        audio_np = (
            np.frombuffer(byte_chunk, dtype=np.int16).astype(np.float32) / 32768.0
        )
        return self._transcribe_array(audio_np)

    def transcribe_opus_bytes(self, opus_bytes: bytes) -> str:
        audio_np = decode_opus_bytes(opus_bytes)
        return self._transcribe_array(audio_np)

    def transcribe_opus_file(self, file_path: str) -> str:
        audio_np = decode_opus_file(file_path)
        return self._transcribe_array(audio_np)

    def transcribe_and_analyze(self, opus_bytes: bytes) -> dict:
        transcript = self.transcribe_opus_bytes(opus_bytes)
        analysis = analyze_disfluencies(transcript)
        return {
            "transcript": transcript,
            "stutter_flag": analysis["stutter_flag"],
            "disfluency_rate": analysis["disfluency_rate"],
            "details": analysis,
        }

def verify_password(self, email: str, password: str) -> bool:
    """
    B01: Verify a login attempt by email + password. Returns True if it matches.
    Uses constant-time comparison to prevent timing attacks.
    """
    try:
        with self._connection() as con:
            row = con.execute(
                "SELECT password_hash FROM users WHERE LOWER(email) = ?",
                (self.normalize_email(email),),
            ).fetchone()
        if not row or not row["password_hash"]:
            return False
        return self._verify_hash(password, row["password_hash"])
    except Exception as e:
        self.logger.error(f"verify_password failed: {e}")
        return False

@app.post("/api/auth/login")
@limiter.limit("10/minute")
def login(request: Request, creds: LoginRequest):
    db_user = db.get_user_by_email(creds.email)
    if not db_user or not db.verify_password(creds.email, creds.password):
        if not db_user:
            # Burn the same hashing time so response time doesn't reveal
            # whether the email is registered.
            DBManager._hash_password(creds.password)
        # One message for "no such account" and "wrong password".
        raise HTTPException(status_code=401, detail="Invalid email or password")
    return {"token": create_token(db_user["user_id"], JWT_SECRET), "user": db_user}

