def get_user_by_email(self, email: str) -> Optional[Dict[str, Any]]:
    """Returns user record WITHOUT password_hash for safety."""
    try:
        with self._connection() as con:
            row = con.execute(
                "SELECT user_id, username, email, created_at FROM users WHERE LOWER(email) = ?",
                (self.normalize_email(email),),
            ).fetchone()
        return dict(row) if row else None
    except Exception as e:
        self.logger.error(f"get_user_by_email failed: {e}")
        return None

def get_user_by_username(self, username: str) -> Optional[Dict[str, Any]]:
    """Returns user record WITHOUT password_hash for safety."""
    try:
        with self._connection() as con:
            row = con.execute(
                "SELECT user_id, username, email, created_at FROM users WHERE username = ?",
                (username,),
            ).fetchone()
        return dict(row) if row else None
    except Exception as e:
        self.logger.error(f"get_user_by_username failed: {e}")
        return None

